What does this program print?

```swift
enum Shape {
    case circle(radius: Int)
    case rectangle(width: Int, height: Int)
    case square(side: Int)
}
func area(_ s: Shape) -> Int {
    switch s {
    case .circle(let r): 3 * r * r
    case .rectangle(let w, let h): w * h
    case .square(let side): side * side
    }
}
print([Shape.circle(radius: 2), .rectangle(width: 3, height: 5), .square(side: 4)].map(area))
```

Assigning to a property inside its own `didSet` does not trigger the observer again. What does this program print?

```swift
struct Thermostat {
    var target = 20 {
        didSet {
            if target > 26 { target = 26 }
        }
    }
}
var t = Thermostat()
t.target = 30
t.target -= 2
print(t.target)
```
